<script setup>
import { computed } from 'vue'

// Props para receber as cores dos projetos e o índice do projeto em hover
const props = defineProps({
  projectColors: {
    type: Array,
    default: () => ['#3EFF88', '#C64CFF', '#FFD13B', '#FF3030', '#49F9FF']
  },
  hoveredProjectIndex: {
    type: Number,
    default: -1
  }
})

// Função para escurecer uma cor
const darkenColor = (color, percent = 20) => {
  const hex = color.replace('#', '')
  const r = parseInt(hex.substr(0, 2), 16)
  const g = parseInt(hex.substr(2, 2), 16)
  const b = parseInt(hex.substr(4, 2), 16)
  
  const darkenedR = Math.floor(r * (1 - percent / 100))
  const darkenedG = Math.floor(g * (1 - percent / 100))
  const darkenedB = Math.floor(b * (1 - percent / 100))
  
  return `#${darkenedR.toString(16).padStart(2, '0')}${darkenedG.toString(16).padStart(2, '0')}${darkenedB.toString(16).padStart(2, '0')}`
}

// Todos os grupos de livros disponíveis no BookShelf
const allBookGroups = [
  ['book_10', 'book_11', 'book_60', 'book_61'], // Grupo 1 - Prateleira superior direita (4 livros)
  ['book_20', 'book_21'], // Grupo 2 - Prateleira superior centro-esquerda (2 livros)
  ['book_30', 'book_31'], // Grupo 3 - Prateleira superior centro-direita (2 livros)
  ['book_40', 'book_41'], // Grupo 4 - Prateleira superior centro (2 livros)
  ['book_50', 'book_51'], // Grupo 5 - Prateleira superior centro (2 livros)
  // Grupo 6 - book_70, book_71, book_72, book_73, book_74 (grupo especial com opacidade)
  ['book_80', 'book_81'], // Grupo 7 - Prateleira média (2 livros)
  ['book_90', 'book_91'], // Grupo 8 - Prateleira média (2 livros)
  ['book_a0', 'book_a1'], // Grupo 9 - Prateleira média (2 livros)
  ['book_b0', 'book_b1'], // Grupo 10 - Prateleira média (2 livros)
  ['book_c0', 'book_c1'], // Grupo 11 - Prateleira média (2 livros)
  ['book_d0', 'book_d1'], // Grupo 12 - Prateleira média (2 livros)
  ['book_e0', 'book_e1'], // Grupo 13 - Prateleira média (2 livros)
  ['book_f0', 'book_f1'], // Grupo 14 - Prateleira inferior (2 livros)
  ['book_g0', 'book_g1'], // Grupo 15 - Prateleira inferior (2 livros)
  ['book_h0', 'book_h1'], // Grupo 16 - Prateleira inferior (2 livros)
  ['book_i0', 'book_i1'], // Grupo 17 - Prateleira inferior (2 livros)
  ['book_j0', 'book_j1'], // Grupo 18 - Prateleira inferior (2 livros)
  ['book_k0', 'book_k1'], // Grupo 19 - Prateleira inferior (2 livros)
  ['book_l0', 'book_l1'], // Grupo 20 - Prateleira inferior esquerda (2 livros)
  ['book_m0', 'book_m1'], // Grupo 21 - Prateleira inferior esquerda (2 livros)
  ['book_n0', 'book_n1'], // Grupo 22 - Prateleira inferior esquerda (2 livros)
  ['book_o0', 'book_o1'], // Grupo 23 - Prateleira inferior esquerda (2 livros)
  ['book_p0', 'book_p1'], // Grupo 24 - Prateleira inferior esquerda (2 livros)
  ['book_q0', 'book_q1'], // Grupo 25 - Prateleira inferior esquerda (2 livros)
  ['book_r0', 'book_r1']  // Grupo 26 - Prateleira inferior esquerda (2 livros)
]

// Mapeamento dinâmico de projetos para grupos de livros
// Só usa quantos projetos existem, deixando o resto como "enfeite"
const projectBookGroups = computed(() => {
  const mapping = {}
  const numProjects = props.projectColors.length
  
  for (let i = 0; i < numProjects && i < allBookGroups.length; i++) {
    mapping[i] = allBookGroups[i]
  }
  
  return mapping
})

// Função para verificar se um livro deve ser destacado
const shouldHighlightBook = (bookId) => {
  if (props.hoveredProjectIndex === -1) return false
  const bookGroup = projectBookGroups.value[props.hoveredProjectIndex]
  return bookGroup && bookGroup.includes(bookId)
}

// Cores computadas - versões escurecidas e originais
const bookColors = computed(() => {
  const colors = {}
  const numProjects = props.projectColors.length
  
  // Mapear cores para os grupos de livros baseado nos projetos disponíveis
  for (let i = 0; i < numProjects && i < allBookGroups.length; i++) {
    const projectColor = props.projectColors[i]
    const bookGroup = allBookGroups[i]
    
    bookGroup.forEach((bookId, index) => {
      // Alternar entre versão mais escura (40%) e menos escura (20%)
      const darkenPercent = index % 2 === 0 ? 40 : 20
      // Remover o prefixo 'book_' para criar a chave
      const colorKey = bookId.replace('book_', 'book')
      colors[colorKey] = darkenColor(projectColor, darkenPercent)
    })
  }
  
  return colors
})
</script>

<style scoped>
/* Efeito de destaque para os livros */
path {
  transition: all 0.3s ease;
}

.book-highlighted {
  filter: brightness(1.4) drop-shadow(0 0 8px currentColor);
  transform: scale(1.05);
  transform-origin: center;
}

/* Garantir que apenas os livros não destacados fiquem mais sutis */
svg:has(.book-highlighted) path[id^="book_"]:not(.book-highlighted) {
  opacity: 0.6;
}
</style>